WITH with_windows AS (SELECT *, ROUND(salary / SUM(salary) OVER (PARTITION BY dept_id), 4) AS salary_share, ROUND(salary / SUM(salary) OVER (PARTITION BY manager_id), 4) AS salary_share_2, LEAD(salary, 1) OVER w_part AS next_salary, NTILE(4) OVER w_recent AS salary_bucket FROM employees WHERE level = 'L2' WINDOW w_part AS (ORDER BY hire_date, id), w_recent AS (ORDER BY salary, id)) SELECT s.id, s.full_name, s.email, s.dept_id, s.job_title, s.salary, s.hire_date, s.is_remote, s.level, (SELECT SUM(x.salary) FROM employees x WHERE x.dept_id = s.dept_id) AS sum_employee_salary FROM with_windows s ORDER BY sum_employee_salary DESC
